from collections import defaultdict
def find_repeats(s, k=20):
    d=defaultdict(list)
    for i in range(len(s)-k+1):
        d[s[i:i+k]].append(i)
    hits={}
    for key,pos in d.items():
        if len(pos)>1:
            hits[key]=pos
    return hits

