seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq)
comp=str.maketrans("ACGT","TGCA")
rc=seq.translate(comp)[::-1]
def orfs(s, strand, minaa=60):
    res=[]
    for frame in range(3):
        i=frame
        while i < len(s)-2:
            if s[i:i+3]=="ATG":
                j=i
                while j < len(s)-2 and s[j:j+3] not in ("TAA","TAG","TGA"):
                    j+=3
                if j-i >= minaa*3:
                    res.append((i,j+3,strand,(j-i)//3))
                i=j+3
            else:
                i+=3
    out=[]
    for a,b,st,L in res:
        if st=="+":
            out.append((a+1,b,st,L, seq[a:a+3], seq[b-3:b]))
        else:
            out.append((n-b+1,n-a,st,L, rc[a:a+3], rc[b-3:b]))
    return out
